int check_feasible(long long max_sum, const int* arr, int n, int k) {
    int count = 1;
    long long current = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > max_sum) return 0;
        if (current + arr[i] > max_sum) {
            count++;
            current = arr[i];
        } else {
            current += arr[i];
        }
    }
