        high += arr[i];
    }
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check_feasible(mid, arr, n, k)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
