        long long m2 = high - (high - low) / 3;
        if (func(m1) < func(m2)) low = m1;
        else high = m2;
    }
    long long best_x = low;
    long long best_val = func(low);
    for (long long x = low + 1; x <= high; x++) {
        long long val = func(x);
        if (val > best_val) {
